namespace RecipeHub.Data;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;

    public RecipeService()
    {
        _recipes = new List<Recipe>
        {
            new() { Id = 1, Title = "Classic Margherita Pizza", Category = "Italian", Ingredients = "Pizza dough, San Marzano tomatoes, Fresh mozzarella, Fresh basil, Olive oil, Salt", Steps = "1. Preheat oven to 475°F.\n2. Roll out dough on floured surface.\n3. Spread crushed tomatoes evenly.\n4. Add torn mozzarella pieces.\n5. Bake 10-12 minutes until crust is golden.\n6. Top with fresh basil and drizzle olive oil." },
            new() { Id = 2, Title = "Chicken Tikka Masala", Category = "Indian", Ingredients = "Chicken thighs, Yogurt, Garam masala, Tomato sauce, Heavy cream, Onion, Garlic, Ginger, Cilantro", Steps = "1. Marinate chicken in yogurt and spices for 2 hours.\n2. Grill or broil chicken until charred.\n3. Sauté onion, garlic, and ginger.\n4. Add tomato sauce and simmer 15 minutes.\n5. Stir in cream and cooked chicken.\n6. Garnish with cilantro and serve with rice." },
            new() { Id = 3, Title = "Beef Tacos", Category = "Mexican", Ingredients = "Ground beef, Taco shells, Lettuce, Tomato, Cheddar cheese, Sour cream, Taco seasoning", Steps = "1. Brown ground beef in skillet.\n2. Add taco seasoning and water, simmer 5 minutes.\n3. Warm taco shells in oven.\n4. Fill shells with beef.\n5. Top with lettuce, tomato, cheese, and sour cream." },
            new() { Id = 4, Title = "Spaghetti Carbonara", Category = "Italian", Ingredients = "Spaghetti, Guanciale, Eggs, Pecorino Romano, Black pepper", Steps = "1. Cook spaghetti in salted water until al dente.\n2. Crisp guanciale in a pan.\n3. Whisk eggs with grated pecorino and pepper.\n4. Toss hot pasta with guanciale.\n5. Remove from heat, stir in egg mixture quickly.\n6. Serve immediately with extra pecorino." },
            new() { Id = 5, Title = "Pad Thai", Category = "Asian", Ingredients = "Rice noodles, Shrimp, Eggs, Bean sprouts, Peanuts, Lime, Fish sauce, Tamarind paste, Sugar", Steps = "1. Soak rice noodles in warm water 30 minutes.\n2. Stir-fry shrimp until pink, set aside.\n3. Scramble eggs in the same pan.\n4. Add noodles and sauce (tamarind, fish sauce, sugar).\n5. Toss with shrimp, bean sprouts.\n6. Serve with crushed peanuts and lime." },
            new() { Id = 6, Title = "Guacamole", Category = "Mexican", Ingredients = "Avocados, Lime juice, Red onion, Jalapeño, Cilantro, Tomato, Salt", Steps = "1. Halve and pit avocados.\n2. Mash to desired consistency.\n3. Stir in diced onion, jalapeño, tomato.\n4. Add lime juice and chopped cilantro.\n5. Season with salt.\n6. Serve immediately with tortilla chips." },
            new() { Id = 7, Title = "Chocolate Chip Cookies", Category = "Desserts", Ingredients = "Butter, Sugar, Brown sugar, Eggs, Vanilla, Flour, Baking soda, Salt, Chocolate chips", Steps = "1. Cream butter and sugars until fluffy.\n2. Beat in eggs and vanilla.\n3. Mix flour, baking soda, and salt separately.\n4. Combine wet and dry ingredients.\n5. Fold in chocolate chips.\n6. Bake at 375°F for 9-11 minutes." },
            new() { Id = 8, Title = "Miso Soup", Category = "Asian", Ingredients = "Dashi stock, White miso paste, Tofu, Wakame seaweed, Green onions", Steps = "1. Heat dashi stock until simmering.\n2. Dissolve miso paste in a ladle of warm broth.\n3. Add dissolved miso back to pot.\n4. Add cubed tofu and rehydrated wakame.\n5. Heat gently (do not boil).\n6. Serve topped with sliced green onions." },
        };
        _nextId = 9;
    }

    public IReadOnlyList<Recipe> GetAll() => _recipes.AsReadOnly();

    public IReadOnlyList<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();

    public IReadOnlyList<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _nextId++;
        _recipes.Add(recipe);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is null || stars < 1 || stars > 5) return;

        var totalStars = recipe.AverageRating * recipe.RatingCount + stars;
        recipe.RatingCount++;
        recipe.AverageRating = totalStars / recipe.RatingCount;
    }
}

@rendermode InteractiveServer
@inject RecipeHub.Data.RecipeService RecipeService

<div class="star-rating">
    <span class="rating-label">Rate this recipe:</span>
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <button class="star-btn @(star <= _selectedRating ? "selected" : "")"
                @onclick="() => Rate(star)"
                title="@star star(s)"
                disabled="@_hasRated">
            @(star <= _selectedRating ? "★" : "☆")
        </button>
    }
    @if (_hasRated)
    {
        <span class="rating-thanks">Thanks for rating!</span>
    }
</div>

@if (_recipe is not null && _recipe.RatingCount > 0)
{
    <p class="rating-summary">
        Average: @_recipe.AverageRating.ToString("F1") / 5
        (@_recipe.RatingCount rating@(_recipe.RatingCount == 1 ? "" : "s"))
    </p>
}

@code {
    [Parameter] public int RecipeId { get; set; }

    private RecipeHub.Data.Recipe? _recipe;
    private int _selectedRating;
    private bool _hasRated;

    protected override void OnParametersSet()
    {
        _recipe = RecipeService.GetById(RecipeId);
    }

    private void Rate(int stars)
    {
        if (_hasRated) return;
        _selectedRating = stars;
        _hasRated = true;
        RecipeService.AddRating(RecipeId, stars);
        _recipe = RecipeService.GetById(RecipeId);
    }
}

@page "/categories/{CategoryName}"
@inject RecipeHub.Data.RecipeService RecipeService

<PageTitle>@CategoryName Recipes - RecipeHub</PageTitle>

<h1>@CategoryName Recipes</h1>

@if (_recipes.Count == 0)
{
    <p>No recipes found in this category.</p>
}
else
{
    <div class="row">
        @foreach (var recipe in _recipes)
        {
            <div class="col-md-6 mb-3">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text text-muted">@recipe.Category</p>
                        <a href="/recipe/@recipe.Id" class="btn btn-primary">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

<a href="/" class="btn btn-outline-secondary mt-3">← Back to Categories</a>

@code {
    [Parameter] public string CategoryName { get; set; } = string.Empty;

    private IReadOnlyList<RecipeHub.Data.Recipe> _recipes = [];

    protected override void OnParametersSet()
    {
        _recipes = RecipeService.GetByCategory(CategoryName);
    }
}

@page "/recipe/{Id:int}"
@inject RecipeHub.Data.RecipeService RecipeService

@if (_recipe is null)
{
    <PageTitle>Recipe Not Found - RecipeHub</PageTitle>
    <h1>Recipe Not Found</h1>
    <p>The recipe you're looking for doesn't exist.</p>
}
else
{
    <PageTitle>@_recipe.Title - RecipeHub</PageTitle>

    <h1>@_recipe.Title</h1>
    <span class="badge bg-secondary mb-3">@_recipe.Category</span>

    <h3>Ingredients</h3>
    <ul>
        @foreach (var ingredient in _recipe.Ingredients.Split(',', StringSplitOptions.TrimEntries))
        {
            <li>@ingredient</li>
        }
    </ul>

    <h3>Steps</h3>
    <ol>
        @foreach (var step in _recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
        {
            var text = System.Text.RegularExpressions.Regex.Replace(step, @"^\d+\.\s*", "");
            <li>@text</li>
        }
    </ol>

    <hr />
    <RecipeHub.Components.Shared.StarRating RecipeId="@_recipe.Id" />

    <a href="/categories/@_recipe.Category" class="btn btn-outline-secondary mt-3">← Back to @_recipe.Category</a>
}

@code {
    [Parameter] public int Id { get; set; }

    private RecipeHub.Data.Recipe? _recipe;

    protected override void OnParametersSet()
    {
        _recipe = RecipeService.GetById(Id);
    }
}

@page "/submit"
@rendermode InteractiveServer
@inject RecipeHub.Data.RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe - RecipeHub</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (_submitted)
{
    <div class="alert alert-success">
        <strong>Recipe submitted!</strong> Your recipe "@_model.Title" has been added.
        <a href="/recipe/@_newRecipeId">View it here</a>.
    </div>
}

<EditForm Model="_model" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
    <DataAnnotationsValidator />
    <ValidationSummary class="text-danger" />

    <div class="mb-3">
        <label for="title" class="form-label">Recipe Title</label>
        <InputText id="title" @bind-Value="_model.Title" class="form-control" placeholder="e.g. Grandma's Apple Pie" />
        <ValidationMessage For="() => _model.Title" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="category" class="form-label">Category</label>
        <InputSelect id="category" @bind-Value="_model.Category" class="form-select">
            <option value="">-- Select a category --</option>
            <option value="Italian">Italian</option>
            <option value="Mexican">Mexican</option>
            <option value="Indian">Indian</option>
            <option value="Asian">Asian</option>
            <option value="Desserts">Desserts</option>
            <option value="Other">Other</option>
        </InputSelect>
        <ValidationMessage For="() => _model.Category" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="ingredients" class="form-label">Ingredients</label>
        <InputTextArea id="ingredients" @bind-Value="_model.Ingredients" class="form-control" rows="4"
            placeholder="List ingredients separated by commas" />
        <ValidationMessage For="() => _model.Ingredients" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="steps" class="form-label">Steps</label>
        <InputTextArea id="steps" @bind-Value="_model.Steps" class="form-control" rows="6"
            placeholder="Describe each step on a new line" />
        <ValidationMessage For="() => _model.Steps" class="text-danger" />
    </div>

    <button type="submit" class="btn btn-success">Submit Recipe</button>
</EditForm>

@code {
    private RecipeFormModel _model = new();
    private bool _submitted;
    private int _newRecipeId;

    private void HandleSubmit()
    {
        var recipe = new RecipeHub.Data.Recipe
        {
            Title = _model.Title,
            Category = _model.Category,
            Ingredients = _model.Ingredients,
            Steps = _model.Steps
        };
        RecipeService.AddRecipe(recipe);
        _newRecipeId = recipe.Id;
        _submitted = true;
        _model = new();
    }

    private class RecipeFormModel
    {
        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Title is required")]
        public string Title { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Category is required")]
        public string Category { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Ingredients are required")]
        public string Ingredients { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Steps are required")]
        public string Steps { get; set; } = string.Empty;
    }
}

