toolArgs.file_text:
@page "/categories/{CategoryName}"
@inject RecipeHub.Data.RecipeService RecipeService

<PageTitle>@CategoryName Recipes - RecipeHub</PageTitle>

<h1>@CategoryName Recipes</h1>

@if (_recipes.Count == 0)
{
    <p>No recipes found in this category.</p>
}
else
{
    <div class="row">
        @foreach (var recipe in _recipes)
        {
            <div class="col-md-6 mb-3">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text text-muted">@recipe.Category</p>
                        <a href="/recipe/@recipe.Id" class="btn btn-primary">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

<a href="/" class="btn btn-outline-secondary mt-3">← Back to Categories</a>

@code {
    [Parameter] public string CategoryName { get; set; } = string.Empty;

    private IReadOnlyList<RecipeHub.Data.Recipe> _recipes = [];

    protected override void OnParametersSet()
    {
        _recipes = RecipeService.GetByCategory(CategoryName);
    }
}

@page "/recipe/{Id:int}"
@inject RecipeHub.Data.RecipeService RecipeService

@if (_recipe is null)
{
    <PageTitle>Recipe Not Found - RecipeHub</PageTitle>
    <h1>Recipe Not Found</h1>
    <p>The recipe you're looking for doesn't exist.</p>
}
else
{
    <PageTitle>@_recipe.Title - RecipeHub</PageTitle>

    <h1>@_recipe.Title</h1>
    <span class="badge bg-secondary mb-3">@_recipe.Category</span>

    <h3>Ingredients</h3>
    <ul>
        @foreach (var ingredient in _recipe.Ingredients.Split(',', StringSplitOptions.TrimEntries))
        {
            <li>@ingredient</li>
        }
    </ul>

    <h3>Steps</h3>
    <ol>
        @foreach (var step in _recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
        {
            var text = System.Text.RegularExpressions.Regex.Replace(step, @"^\d+\.\s*", "");
            <li>@text</li>
        }
    </ol>

    <hr />
    <RecipeHub.Components.Shared.StarRating RecipeId="@_recipe.Id" />

    <a href="/categories/@_recipe.Category" class="btn btn-outline-secondary mt-3">← Back to @_recipe.Category</a>
}

@code {
    [Parameter] public int Id { get; set; }

    private RecipeHub.Data.Recipe? _recipe;

    protected override void OnParametersSet()
    {
        _recipe = RecipeService.GetById(Id);
    }
}

@page "/submit"
@rendermode InteractiveServer
@inject RecipeHub.Data.RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe - RecipeHub</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (_submitted)
{
    <div class="alert alert-success">
        <strong>Recipe submitted!</strong> Your recipe "@_model.Title" has been added.
        <a href="/recipe/@_newRecipeId">View it here</a>.
    </div>
}

<EditForm Model="_model" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
    <DataAnnotationsValidator />
    <ValidationSummary class="text-danger" />

    <div class="mb-3">
        <label for="title" class="form-label">Recipe Title</label>
        <InputText id="title" @bind-Value="_model.Title" class="form-control" placeholder="e.g. Grandma's Apple Pie" />
        <ValidationMessage For="() => _model.Title" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="category" class="form-label">Category</label>
        <InputSelect id="category" @bind-Value="_model.Category" class="form-select">
            <option value="">-- Select a category --</option>
            <option value="Italian">Italian</option>
            <option value="Mexican">Mexican</option>
            <option value="Indian">Indian</option>
            <option value="Asian">Asian</option>
            <option value="Desserts">Desserts</option>
            <option value="Other">Other</option>
        </InputSelect>
        <ValidationMessage For="() => _model.Category" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="ingredients" class="form-label">Ingredients</label>
        <InputTextArea id="ingredients" @bind-Value="_model.Ingredients" class="form-control" rows="4"
            placeholder="List ingredients separated by commas" />
        <ValidationMessage For="() => _model.Ingredients" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="steps" class="form-label">Steps</label>
        <InputTextArea id="steps" @bind-Value="_model.Steps" class="form-control" rows="6"
            placeholder="Describe each step on a new line" />
        <ValidationMessage For="() => _model.Steps" class="text-danger" />
    </div>

    <button type="submit" class="btn btn-success">Submit Recipe</button>
</EditForm>

@code {
    private RecipeFormModel _model = new();
    private bool _submitted;
    private int _newRecipeId;

    private void HandleSubmit()
    {
        var recipe = new RecipeHub.Data.Recipe
        {
            Title = _model.Title,
            Category = _model.Category,
            Ingredients = _model.Ingredients,
            Steps = _model.Steps
        };
        RecipeService.AddRecipe(recipe);
        _newRecipeId = recipe.Id;
        _submitted = true;
        _model = new();
    }

    private class RecipeFormModel
    {
        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Title is required")]
        public string Title { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Category is required")]
        public string Category { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Ingredients are required")]
        public string Ingredients { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Steps are required")]
        public string Steps { get; set; } = string.Empty;
    }
}
